INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('aceee58f-9865-4095-8bff-bef66f5baa73'::uuid, 'card_description', 'Large figures in many colours are a striking feature of this complex. Its main mound, a stepped pyramid with at least six platforms, was about 30 metres high and almost four-sided.', 'Large polychrome figures are a striking feature of Mojeque in northern Peru, whose main mound is a stepped pyramid of at least six platforms, about 30 m in height and almost quadrangular.', 'teaser-card-s048-rollback:aceee58f-9865-4095-8bff-bef66f5baa73:card_description', 'rollback of teaser-card-s048: card_description ''Large polychrome figures are a striking feature of Mojeque in northern Peru, whose main mound is a stepped pyramid of at least six platforms, about 30 m in height and almost quadrangular.'' restored on Mojeque', 'ccd191d1110b1830f5ab70e334d8aa8e362a0d48bfede6b575081f75be608e48|d50711a1b61ec149d3f96d605fe4c7c3fc99481a8d7b02ac773ec047baeb1a24|d50711a1b61ec149d3f96d605fe4c7c3fc99481a8d7b02ac773ec047baeb1a24', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Large figures in many colours are a striking feature of this complex. Its main mound, a stepped pyramid with at least six platforms, was about 30 metres high and almost four-sided."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the complex has large figures in many colours (polychrome) [S3]; these figures are a striking feature of the complex [S3]; the site has a main mound [S6]; the main mound is a stepped pyramid [S6]; it has at least six platforms [S6]; it was about 30 metres high [S7]; it was almost four-sided (quadrangular) [S7]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Large figures are a striking feature of this complex [SUPPORTED: https://bruceowen.com/worldprehist/3250s19.htm]; The figures are in many colours [SUPPORTED: https://www.arqueologiadelperu.com.ar/moxeque.htm]; The site is a complex with more than one mound, of which one is the main mound [SUPPORTED: https://bruceowen.com/worldprehist/3250s19.htm]; Its main mound is a stepped pyramid [SUPPORTED: https://bruceowen.com/worldprehist/3250s19.htm]; The main mound has at least six platforms [SUPPORTED: https://www.arqueologiadelperu.com.ar/moxeque.htm]; The main mound was about 30 metres high [SUPPORTED: https://bruceowen.com/worldprehist/3250s19.htm]; The main mound was almost four-sided [SUPPORTED: https://www.jqjacobs.net/andes/coast.html]"}]'::jsonb),
    ('b01e5465-5f19-408e-8a56-4d04f6575537'::uuid, 'card_description', 'Collapsed in 1862, this dolmen was restored that same year. The dolmen dates from the New Stone Age and stands on three granite supports topped by a single capstone.', 'On Shilstone Farm near Drewsteignton, three granite supports of Spinsters'' Rock hold up a capstone of 4.5 by 3.1 metres. The Neolithic dolmen collapsed in 1862 and was restored that year.', 'teaser-card-s048-rollback:b01e5465-5f19-408e-8a56-4d04f6575537:card_description', 'rollback of teaser-card-s048: card_description "On Shilstone Farm near Drewsteignton, three granite supports of Spinsters'' Rock hold up a capstone of 4.5 by 3.1 metres. The Neolithic dolmen collapsed in 1862 and was restored that year." restored on Spinsters'' Rock', '449636d8c5b3243b77d8ffe7ef87483c6b98eb8e533d002015a1c48912be0815|14bba77e961191d1a52d3fdaab1ca7fc1ff4db00a25a48c484189f19ee990726|14bba77e961191d1a52d3fdaab1ca7fc1ff4db00a25a48c484189f19ee990726', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Collapsed in 1862, this dolmen was restored that same year. The dolmen dates from the New Stone Age and stands on three granite supports topped by a single capstone."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "it is a dolmen [S1]; it collapsed in 1862 [S4]; it was restored the same year [S4]; it dates from the Neolithic [S1]; it stands on three granite supports [S3]; the supports are topped by a capstone [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This dolmen collapsed in 1862 [SUPPORTED: https://www.stonepages.com/england/spintersrock.html]; It was restored that same year [SUPPORTED: https://www.stonepages.com/england/spintersrock.html]; It is a dolmen [SUPPORTED: https://www.britainexpress.com/counties/devon/ancient/spinsters-rock.htm]; The dolmen dates from the New Stone Age [SUPPORTED: https://www.britainexpress.com/counties/devon/ancient/spinsters-rock.htm]; It stands on three supports [SUPPORTED: https://www.britainexpress.com/counties/devon/ancient/spinsters-rock.htm]; The supports are granite [SUPPORTED: https://www.thenorthernantiquarian.org/2024/10/02/spinsters/]; The supports are topped by a single capstone [SUPPORTED: https://www.thenorthernantiquarian.org/2024/10/02/spinsters/]"}]'::jsonb),
    ('b048a095-8e3e-41af-a715-e785e3a1a51d'::uuid, 'card_description', 'Until a 2013 study, part of this Roman road was known only in isolated sections. Earthworks presumed to be part of Wansdyke followed parts of the route, and in places no trace is in view.', 'Drovers, merchants and travellers used the Roman Road from Silchester to Bath, from Calleva Atrebatum to Aquae Sulis. In places it survives; elsewhere no apparent trace remains in view.', 'teaser-card-s048-rollback:b048a095-8e3e-41af-a715-e785e3a1a51d:card_description', 'rollback of teaser-card-s048: card_description ''Drovers, merchants and travellers used the Roman Road from Silchester to Bath, from Calleva Atrebatum to Aquae Sulis. In places it survives; elsewhere no apparent trace remains in view.'' restored on Roman Road from Silchester to Bath', '3896b174d5f70ca9e626d1e2504bb569a7358cd3009df80602605b4d2886d11c|8c1625097069db514ed07641fc6f507392b1624efe026406a564e587e989a2b7|8c1625097069db514ed07641fc6f507392b1624efe026406a564e587e989a2b7', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Until a 2013 study, part of this Roman road was known only in isolated sections. Earthworks presumed to be part of Wansdyke followed parts of the route, and in places no trace is in view."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-007 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a Roman road [S1]; part of the road was known only in isolated sections [S7]; that lasted until a study published in 2013 [S7]; earthworks followed parts of its route [S3]; those earthworks are presumed to be part of Wansdyke [S3]; in places no trace of the road is in view [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "this Roman road (the site is the Roman road from Silchester to Bath) [SUPPORTED: https://archive.org/download/wiltshirearchaeo1062unse/wiltshirearchaeo1062unse_djvu.txt]; Until a 2013 study (the study that closed the gap dates from 2013) [SUPPORTED: https://archive.org/download/wiltshirearchaeo1062unse/wiltshirearchaeo1062unse_djvu.txt]; Until a 2013 study, part of this Roman road was known only in isolated sections [SUPPORTED: https://archive.org/download/wiltshirearchaeo1062unse/wiltshirearchaeo1062unse_djvu.txt]; Earthworks ... followed parts of the route (Wansdyke earthworks run along parts of the road''s line) [SUPPORTED: http://www.wansdyke21.org.uk/wansdyke/wanwesteast/wanmid6.htm]; Earthworks presumed to be part of Wansdyke (the earthworks on the road''s line are presumed, not proven, to belong to Wansdyke) [SUPPORTED: http://www.wansdyke21.org.uk/wansdyke/wanwesteast/wanmid6.htm]; in places no trace is in view [SUPPORTED: http://www.wansdyke21.org.uk/wansdyke/wanwesteast/wanmid6.htm]"}]'::jsonb),
    ('b0f8cf11-8472-422b-9e00-cf45b1d80683'::uuid, 'card_description', 'Part of a deer park in medieval times, a training ground in the Second World War. Long before, the roughly circular hillfort, perhaps built in the late Iron Age, covered 2.8 hectares.', 'A rampart and steep banked slope ringed South Weald Camp in Essex, a 2.8 hectare hillfort thought to be late Iron Age, later part of a deer-park and then a WWII training ground.', 'teaser-card-s048-rollback:b0f8cf11-8472-422b-9e00-cf45b1d80683:card_description', 'rollback of teaser-card-s048: card_description ''A rampart and steep banked slope ringed South Weald Camp in Essex, a 2.8 hectare hillfort thought to be late Iron Age, later part of a deer-park and then a WWII training ground.'' restored on South Weald Camp', 'a47162d50689337fb92c4faadd6801bc375d30cda435d7f54c976fc796d46f0e|7eb8e8a372e6a22d014269a537773cabe0ba4650eca1682c99ae55822bd93a60|7eb8e8a372e6a22d014269a537773cabe0ba4650eca1682c99ae55822bd93a60', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Part of a deer park in medieval times, a training ground in the Second World War. Long before, the roughly circular hillfort, perhaps built in the late Iron Age, covered 2.8 hectares."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "in medieval times it was part of a deer park [S5]; in the Second World War it was a training ground [S5]; it is a hillfort [S1]; it is roughly circular [S2]; it was perhaps built in the late Iron Age [S2]; it covered 2.8 hectares [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The fort was part of a deer park in medieval times [SUPPORTED: https://www.esah1852.org.uk/library/files/T3260000.pdf]; The fort was a training ground in the Second World War [SUPPORTED: https://www.esah1852.org.uk/library/files/T3260000.pdf]; It is a hillfort [SUPPORTED: https://www.esah1852.org.uk/library/files/T3260000.pdf]; The hillfort is roughly circular [SUPPORTED: https://www.esah1852.org.uk/library/files/T3260000.pdf]; The hillfort was perhaps built in the late Iron Age [SUPPORTED: https://www.esah1852.org.uk/library/files/T3260000.pdf]; The hillfort covered 2.8 hectares [SUPPORTED: https://www.esah1852.org.uk/library/files/T3260000.pdf]"}]'::jsonb),
    ('b1e4d609-9b3a-4b93-8ad0-e890a880a5dc'::uuid, 'card_description', 'A large aisled hall and a possible bath house came first at this Roman villa. Later a new bath house rose beside six timber buildings, most likely farm buildings or workshops.', 'The first substantial villa found south of the Purbeck Hills, Bucknowle Roman Villa began in the late 1st century AD with an aisled hall and grew to three large buildings and a bath house.', 'teaser-card-s048-rollback:b1e4d609-9b3a-4b93-8ad0-e890a880a5dc:card_description', 'rollback of teaser-card-s048: card_description ''The first substantial villa found south of the Purbeck Hills, Bucknowle Roman Villa began in the late 1st century AD with an aisled hall and grew to three large buildings and a bath house.'' restored on Bucknowle Roman Villa', 'cef5eb965100bea6be3c50a6b04445a535d3f399969675dcf36529da936d896c|40763e5b483acba4f7716e4fe53b13faf81f79aff322ad83ff0cdc10a388bf88|40763e5b483acba4f7716e4fe53b13faf81f79aff322ad83ff0cdc10a388bf88', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A large aisled hall and a possible bath house came first at this Roman villa. Later a new bath house rose beside six timber buildings, most likely farm buildings or workshops."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a Roman villa [S1]; a large aisled hall was built in the first phase [S3]; a possible bath house was built in the first phase [S3]; later a new bath house was built [S4]; the new bath house was built alongside six timber-framed buildings [S4]; those buildings were most likely farm buildings or workshops [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A large aisled hall came first at this villa [SUPPORTED: http://www.wddt.org.uk/bucknowle.htm]; A possible bath house came first at this villa, with the aisled hall [SUPPORTED: http://www.wddt.org.uk/bucknowle.htm]; It is a Roman villa [SUPPORTED: http://www.wddt.org.uk/bucknowle.htm]; Later a new bath house rose [SUPPORTED: http://www.wddt.org.uk/bucknowle.htm]; The new bath house rose beside six timber buildings [SUPPORTED: http://www.wddt.org.uk/bucknowle.htm]; The six timber buildings were most likely farm buildings or workshops [SUPPORTED: http://www.wddt.org.uk/bucknowle.htm]"}]'::jsonb),
    ('b5541bbe-346c-4b3a-831c-21d6aa994adc'::uuid, 'card_description', 'Fear of French attacks had this gate fortified and chained. A sketch of the gate''s north tower shows a room of about 16 by 14 feet, and the south tower probably had a room of similar size.', 'Aldgate once pierced the defensive wall around the City of London. In 1377, fearing a French attack, it was fortified with portcullises and chains; its defences were tested twice.', 'teaser-card-s048-rollback:b5541bbe-346c-4b3a-831c-21d6aa994adc:card_description', 'rollback of teaser-card-s048: card_description ''Aldgate once pierced the defensive wall around the City of London. In 1377, fearing a French attack, it was fortified with portcullises and chains; its defences were tested twice.'' restored on Aldgate', '82e1a3ee0124d41b4880facd959892de93cc957ad6fdb6b5ec31a505ea3f0ccd|8d0f6447cf6c6c9f3a94b8f2092fc4d1139a7e26c4e6e6c71de54a89d885eaaf|8d0f6447cf6c6c9f3a94b8f2092fc4d1139a7e26c4e6e6c71de54a89d885eaaf', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Fear of French attacks had this gate fortified and chained. A sketch of the gate''s north tower shows a room of about 16 by 14 feet, and the south tower probably had a room of similar size."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "it is a gate [S1]; the gate was fortified and chained [S2]; the fortification was due to fear of French attacks [S2]; a sketch of the gate''s north tower exists [S4]; the sketch shows a room of about 16 by 14 feet [S4]; the south tower probably had a room of similar size [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Fear of French attacks had this gate (Aldgate, a gate of the City of London) fortified and chained. [SUPPORTED: https://erenow.org/biographies/chaucers-tale-1386-and-the-road-to-canterbury/4.php]; The gate was fortified and chained. [SUPPORTED: https://www.british-history.ac.uk/london-letter-books/volh/pp63-71]; The gate had a north tower and a south tower. [SUPPORTED: https://erenow.org/biographies/chaucers-tale-1386-and-the-road-to-canterbury/4.php]; A sketch of the gate''s north tower exists. [SUPPORTED: https://erenow.org/biographies/chaucers-tale-1386-and-the-road-to-canterbury/4.php]; The sketch of the north tower shows a room of about 16 by 14 feet. [SUPPORTED: https://erenow.org/biographies/chaucers-tale-1386-and-the-road-to-canterbury/4.php]; The south tower probably had a room of similar size. [SUPPORTED: https://erenow.org/biographies/chaucers-tale-1386-and-the-road-to-canterbury/4.php]"}]'::jsonb),
    ('b5af43a8-181e-47d2-8a3c-0bfdbd445b5e'::uuid, 'card_description', 'Few gates cross Hadrian''s Wall outside a milecastle or fort, and this is one. A single lane ran between guard chambers, with a gate at each end, for passage in two controlled stages.', 'Where Hadrian''s Wall crosses the Knag Burn, east of Housesteads, one lane ran between guard-chambers with a gate at each end: the Knag Burn Gateway, a two-stage passage through the wall.', 'teaser-card-s048-rollback:b5af43a8-181e-47d2-8a3c-0bfdbd445b5e:card_description', 'rollback of teaser-card-s048: card_description "Where Hadrian''s Wall crosses the Knag Burn, east of Housesteads, one lane ran between guard-chambers with a gate at each end: the Knag Burn Gateway, a two-stage passage through the wall." restored on Knag Burn Gateway', '1d041a084632caaddfd8da28eb64e92e58501edcd4481b48104e73d5ab57d444|7eeb122a8eaab63795ca25caec17804ad5dd5256656afc22fbc9d5f28e7abd99|7eeb122a8eaab63795ca25caec17804ad5dd5256656afc22fbc9d5f28e7abd99', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-015", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Few gates cross Hadrian''s Wall outside a milecastle or fort, and this is one. A single lane ran between guard chambers, with a gate at each end, for passage in two controlled stages."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "few gates through Hadrian''s Wall are not part of a milecastle or fort [S3]; this site is one of those gates [S3]; the structure had a single lane [S4]; the lane ran between guard chambers on either side [S4]; there was a gate at each end [S4]; this allowed passage through the wall in two controlled stages [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This (the Knag Burn Gateway) is one of the few gates that cross Hadrian''s Wall outside a milecastle or fort. [SUPPORTED: https://co-curate.ncl.ac.uk/knag-burn-gate-hadrians-wall/]; Few gates cross Hadrian''s Wall outside a milecastle or fort. [SUPPORTED: https://nationaltrails.s3.eu-west-2.amazonaws.com/uploads/walk_11.pdf]; A single lane ran through the gateway. [SUPPORTED: https://co-curate.ncl.ac.uk/wall-mile-36-hadrians-wall/]; The lane ran between guard chambers. [SUPPORTED: https://co-curate.ncl.ac.uk/wall-mile-36-hadrians-wall/]; There was a gate at each end of the lane. [SUPPORTED: https://co-curate.ncl.ac.uk/wall-mile-36-hadrians-wall/]; The arrangement allowed passage in two controlled stages. [SUPPORTED: https://nationaltrails.s3.eu-west-2.amazonaws.com/uploads/walk_11.pdf]"}]'::jsonb),
    ('ba020c96-afeb-452a-8dbc-faf14155c96c'::uuid, 'card_description', 'The remains of fifty-six people were found in this Neolithic burial chamber. Its massive capstone, about 3 m long and wide, now rests with one end on the ground.', 'Near Benllech on Anglesey, the massive capstone of the Neolithic Pant-y-Saer Burial Chamber rests one end on the ground. Excavations found the remains of fifty-six people buried here.', 'teaser-card-s048-rollback:ba020c96-afeb-452a-8dbc-faf14155c96c:card_description', 'rollback of teaser-card-s048: card_description ''Near Benllech on Anglesey, the massive capstone of the Neolithic Pant-y-Saer Burial Chamber rests one end on the ground. Excavations found the remains of fifty-six people buried here.'' restored on Pant-y-Saer Burial Chamber', '1658791aabd3f385d64711266139cf0524f1fd5120bbd8a8dd0e9bedd2b1d885|5d4de326e5a19078763b13728c2581f9c5f1b5d854f06cd17996adfba1a2bf40|5d4de326e5a19078763b13728c2581f9c5f1b5d854f06cd17996adfba1a2bf40', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-015", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The remains of fifty-six people were found in this Neolithic burial chamber. Its massive capstone, about 3 m long and wide, now rests with one end on the ground."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the remains of fifty-six people were found at the site [S3]; the site is a Neolithic burial chamber [S1, S2]; it has a massive capstone [S2]; the capstone is about 3 m long and 3 m wide [S4]; the capstone now rests with one end on the ground [S2, S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The remains of fifty-six people were found in this burial chamber [SUPPORTED: https://www.anglesey-history.co.uk/places/prehistoric-monuments/pant-y-saer/]; It is a Neolithic burial chamber [SUPPORTED: https://coflein.gov.uk/en/site/95529/]; Its capstone is massive [SUPPORTED: http://www.stone-circles.org.uk/stone/pantysaer.htm]; The capstone is about 3 m long and wide [SUPPORTED: http://www.stone-circles.org.uk/stone/pantysaer.htm]; The capstone now rests with one end on the ground [SUPPORTED: http://www.stone-circles.org.uk/stone/pantysaer.htm]"}]'::jsonb),
    ('bcf13ede-0f30-415a-85ea-59bfd6d4cce4'::uuid, 'card_description', 'Named after the Roman god of war, this fort guarded a road through a mountain pass. Huns under Uldin took the fort during an attack on the Eastern Roman Empire, apparently by treachery.', 'Named after Mars, Roman god of war, the garrison of Castra Martis guarded the road through the Vrashka Chuka pass. In 408 the Huns under Uldin took it, apparently by treachery.', 'teaser-card-s048-rollback:bcf13ede-0f30-415a-85ea-59bfd6d4cce4:card_description', 'rollback of teaser-card-s048: card_description ''Named after Mars, Roman god of war, the garrison of Castra Martis guarded the road through the Vrashka Chuka pass. In 408 the Huns under Uldin took it, apparently by treachery.'' restored on Castra Martis', 'edfb54cd79f6fe61e0f39e92e59e74f2fc3a2a97cbc3294ccbc6e5e9d1a737ca|20787234afe20cdb83f3cb75fceea8603e5491642dcc2c638e6d6fc1e60c7789|20787234afe20cdb83f3cb75fceea8603e5491642dcc2c638e6d6fc1e60c7789', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Named after the Roman god of war, this fort guarded a road through a mountain pass. Huns under Uldin took the fort during an attack on the Eastern Roman Empire, apparently by treachery."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-008 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is named after the Roman god of war [S2]; the site was a fort [S1]; it guarded a road through a mountain pass [S2]; Huns under Uldin took the fort [S5, W1]; this happened during an attack on the Eastern Roman Empire [S5]; the Huns took it apparently by treachery [S5]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This fort is named after the Roman god of war [SUPPORTED: https://archaeologyinbulgaria.com/castra-martis-kula-bulgaria/]; This site is a fort [SUPPORTED: https://archaeologyinbulgaria.com/castra-martis-kula-bulgaria/]; This fort guarded a road [SUPPORTED: https://archaeologyinbulgaria.com/castra-martis-kula-bulgaria/]; The road ran through a mountain pass [SUPPORTED: https://archaeologyinbulgaria.com/castra-martis-kula-bulgaria/]; Huns under Uldin took the fort [SUPPORTED: https://www.newadvent.org/fathers/26029.htm]; The fort was taken during an attack on the Eastern Roman Empire [SUPPORTED: https://archaeologyinbulgaria.com/castra-martis-kula-bulgaria/]; The fort was taken apparently by treachery [SUPPORTED: https://www.newadvent.org/fathers/26029.htm]"}, {"source": "web fact W1", "url": "https://bg.wikipedia.org/wiki/%D0%9A%D0%B0%D1%81%D1%82%D1%80%D0%B0_%D0%9C%D0%B0%D1%80%D1%82%D0%B8%D1%81", "quote": "Кастра Мартис е превзета за кратко от хунския вожд Улдис"}]'::jsonb),
    ('bdba33af-64d6-4a74-90f3-4ecf9e512c83'::uuid, 'card_description', 'Shaped like a letter D, this fort shares its valley with two brochs. In 1871, Henry Dryden conducted the first modern survey of the fort, which stands in the upper reaches of the valley.', 'In the upper reaches of Gleann Beag stands Dun Grugaig, a D-shaped fort of a type commonly regarded as a prototype broch, sharing its valley with the brochs of Dun Telve and Dun Troddan.', 'teaser-card-s048-rollback:bdba33af-64d6-4a74-90f3-4ecf9e512c83:card_description', 'rollback of teaser-card-s048: card_description ''In the upper reaches of Gleann Beag stands Dun Grugaig, a D-shaped fort of a type commonly regarded as a prototype broch, sharing its valley with the brochs of Dun Telve and Dun Troddan.'' restored on Dun Grugaig', '4c4cd4cd0e07b3a1e83034d162e5e90221b0ca44c04841d733de0fa44d786d96|4fcd60d3672f9807383cf9a76243d8179a2fe0d1f90faab2bc71bca96f9c2fd6|4fcd60d3672f9807383cf9a76243d8179a2fe0d1f90faab2bc71bca96f9c2fd6', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Shaped like a letter D, this fort shares its valley with two brochs. In 1871, Henry Dryden conducted the first modern survey of the fort, which stands in the upper reaches of the valley."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-008 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is shaped like a letter D [S1, S4]; the site is a fort [S4]; it shares its valley with two brochs [S3]; Henry Dryden conducted the first modern survey of it [S5]; the survey was made in 1871 [S5]; the fort stands in the upper reaches of the valley [S2, S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This fort is shaped like a letter D [SUPPORTED: https://archaeologydataservice.ac.uk/archiveDS/archiveDownload?t=arch-352-1/dissemination/pdf/vol_083/83_012_024.pdf]; This site is a fort [SUPPORTED: https://archaeologydataservice.ac.uk/archiveDS/archiveDownload?t=arch-352-1/dissemination/pdf/vol_083/83_012_024.pdf]; This fort shares its valley with two brochs [SUPPORTED: https://journals.socantscot.org/index.php/psas/article/download/6584/6553/6542]; In 1871, Henry Dryden conducted a survey of the fort [SUPPORTED: https://archaeologydataservice.ac.uk/archiveDS/archiveDownload?t=arch-352-1/dissemination/pdf/vol_083/83_012_024.pdf]; Dryden''s 1871 survey was the first modern survey of the fort [SUPPORTED: https://journals.socantscot.org/index.php/psas/article/download/6584/6553/6542]; The fort stands in the upper reaches of the valley [SUPPORTED: https://archaeologydataservice.ac.uk/archiveDS/archiveDownload?t=arch-352-1/dissemination/pdf/vol_083/83_012_024.pdf]"}]'::jsonb),
    ('bf6f967e-3161-45c3-840d-d68ebff231b7'::uuid, 'card_description', 'Limestone idols shaped like cylinders lay among the dead in these caves. Decorated schist slabs and pots joined them, and around 115 burials have been identified there.', 'In Cascais, evidence points to use of the Caves of Poço Velho as a necropolis, with around 115 burials identified. Finds include limestone votive offerings and decorated schist slabs.', 'teaser-card-s048-rollback:bf6f967e-3161-45c3-840d-d68ebff231b7:card_description', 'rollback of teaser-card-s048: card_description ''In Cascais, evidence points to use of the Caves of Poço Velho as a necropolis, with around 115 burials identified. Finds include limestone votive offerings and decorated schist slabs.'' restored on Caves of Poço Velho', 'ceedfd268970ced26afd7e27572c2c572f84632c71b09befaa1aefd591e54d9a|1f7073752ab6409af65c554af494529e35281a9fa60a097fa7fa647618fffd46|1f7073752ab6409af65c554af494529e35281a9fa60a097fa7fa647618fffd46', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-016", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Limestone idols shaped like cylinders lay among the dead in these caves. Decorated schist slabs and pots joined them, and around 115 burials have been identified there."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a group of caves [S1]; cylindrical limestone idols were found among the funerary remains [S5]; the caves held the dead [S4]; decorated schist slabs were found [S5]; pots were found [S5]; around 115 burials have been identified [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-029 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Idols lay among the dead in these caves. [SUPPORTED: https://www.publico.pt/2009/04/18/jornal/cascais-promove-primeira-visita-guiada--as-grutas-do-poco-velho-no-centro-urbano-303298]; The idols are made of limestone. [SUPPORTED: https://www.publico.pt/2009/04/18/jornal/cascais-promove-primeira-visita-guiada--as-grutas-do-poco-velho-no-centro-urbano-303298]; The idols are shaped like cylinders. [SUPPORTED: https://www.publico.pt/2009/04/18/jornal/cascais-promove-primeira-visita-guiada--as-grutas-do-poco-velho-no-centro-urbano-303298]; The caves were a burial place for the dead. [SUPPORTED: https://www.cascais.pt/noticia/grutas-do-poco-velho-vao-poder-ser-visitadas-por-todos]; Decorated schist slabs joined the idols among the dead. [SUPPORTED: https://cultura.cascais.pt/list/patrimonio/grutas-do-poco-velho-patrimonio-arqueologico]; Pots joined the idols among the dead. [SUPPORTED: https://www.publico.pt/2009/04/18/jornal/cascais-promove-primeira-visita-guiada--as-grutas-do-poco-velho-no-centro-urbano-303298]; Around 115 burials have been identified there. [SUPPORTED: https://ncultura.pt/grutas-do-poco-velho-o-segredo-mais-bem-guardado-de-cascais/]"}]'::jsonb),
    ('c66b25a2-35e6-4d6f-a8bb-683a473f86ca'::uuid, 'card_description', 'Clay jars for storing wine were buried in the ground at this ancient winery. In total 32 were found, and a building of 17 rooms, raised on an existing vineyard, was destroyed by a fire.', 'On the plain of Leivithra lies Kompoloi, an ancient winery of 17 rooms built on a vineyard. Its wine was stored in 32 clay pithoi buried in the ground, until a fire destroyed the building.', 'teaser-card-s048-rollback:c66b25a2-35e6-4d6f-a8bb-683a473f86ca:card_description', 'rollback of teaser-card-s048: card_description ''On the plain of Leivithra lies Kompoloi, an ancient winery of 17 rooms built on a vineyard. Its wine was stored in 32 clay pithoi buried in the ground, until a fire destroyed the building.'' restored on Kompoloi', '22ad502615a4da740befed8d2f0e8333542a422a4597a7e5c7c18842d2f0bebc|1f5fbf262f0e93a80cc3e9e255a7e4b29c901243682d613aa82eb7eb3c4b25dd|1f5fbf262f0e93a80cc3e9e255a7e4b29c901243682d613aa82eb7eb3c4b25dd', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Clay jars for storing wine were buried in the ground at this ancient winery. In total 32 were found, and a building of 17 rooms, raised on an existing vineyard, was destroyed by a fire."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-008 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "clay jars were buried in the ground [S7]; the jars were for storing wine [S7]; the site is an ancient winery [S1]; in total 32 of the jars were found [S8]; a building at the site had 17 rooms [S5]; the building was raised on an existing vineyard [S4]; the building was destroyed by a fire [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Clay jars for storing wine were buried in the ground at this ancient winery [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/farmhouses-of-the-macedonian-olympus/]; This site is an ancient winery [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/farmhouses-of-the-macedonian-olympus/]; The clay jars were for storing wine [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/farmhouses-of-the-macedonian-olympus/]; In total 32 [jars] were found [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/farmhouses-of-the-macedonian-olympus/]; A building of 17 rooms [stood at the site] [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/farmhouses-of-the-macedonian-olympus/]; The building was raised on an existing vineyard [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/farmhouses-of-the-macedonian-olympus/]; The building was destroyed by a fire [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/farmhouses-of-the-macedonian-olympus/]"}]'::jsonb),
    ('c6bd2d66-f54d-4d02-8b14-041414043cf3'::uuid, 'card_description', 'Stuart Piggott first correctly identified this hillfort as unfinished in 1931. Dumps from the abandoned work lie inside, and it has long been suspected that the fort never held a settlement.', 'Ladle Hill is perhaps the best known of Britain''s unfinished hillforts: dumps of material from the abandoned works lie inside, and it has long been suspected no settlement stood there.', 'teaser-card-s048-rollback:c6bd2d66-f54d-4d02-8b14-041414043cf3:card_description', 'rollback of teaser-card-s048: card_description "Ladle Hill is perhaps the best known of Britain''s unfinished hillforts: dumps of material from the abandoned works lie inside, and it has long been suspected no settlement stood there." restored on Ladle Hill', '0114c58b70eb94b926d3d4269fe6ba021aebb5203a5f6ba1a03289c7781e3e58|fae8eee164155c50564d5ec6c361f03a0a841f4535d4bb2edd86fc9a8811f54d|fae8eee164155c50564d5ec6c361f03a0a841f4535d4bb2edd86fc9a8811f54d', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Stuart Piggott first correctly identified this hillfort as unfinished in 1931. Dumps from the abandoned work lie inside, and it has long been suspected that the fort never held a settlement."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-008 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Stuart Piggott was the first to identify it correctly as an unfinished hillfort [S2]; he did so in 1931 [S2]; the site is an unfinished hillfort [S1, S2]; dumps of material from the abandoned construction work lie inside it [S4]; it has long been suspected that the fort never held a settlement [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Stuart Piggott first correctly identified this hillfort as unfinished in 1931 [SUPPORTED: https://archaeologydataservice.ac.uk/archiveDS/archiveDownload?t=arch-1416-1/dissemination/pdf/978-1873-592854_Hillforts_ALL_250.pdf]; This site is a hillfort [SUPPORTED: https://archaeologydataservice.ac.uk/archiveDS/archiveDownload?t=arch-1416-1/dissemination/pdf/978-1873-592854_Hillforts_ALL_250.pdf]; The hillfort is unfinished, its construction work abandoned [SUPPORTED: https://collections.hampshireculture.org.uk/topic/unfinished-hill-fort-and-english-earl]; Dumps from the abandoned work lie inside [SUPPORTED: https://collections.hampshireculture.org.uk/topic/unfinished-hill-fort-and-english-earl]; It has long been suspected that the fort never held a settlement [SUPPORTED: https://archaeologydataservice.ac.uk/archiveDS/archiveDownload?t=arch-1416-1/dissemination/pdf/978-1873-592854_Hillforts_ALL_250.pdf]"}]'::jsonb),
    ('c961d960-661c-4406-a645-4185684b4c89'::uuid, 'card_description', 'Carved crosses on the walls of this headland sanctuary suggest a Christian ending. A religious complex was set up here around the 3rd century BC and stayed in use through the Roman period.', 'On the southwest coast of Gozo, the promontory of Ras il-Wardija holds a Punic-Roman sanctuary. Carved crosses on its walls suggest it later became a Christian place of worship.', 'teaser-card-s048-rollback:c961d960-661c-4406-a645-4185684b4c89:card_description', 'rollback of teaser-card-s048: card_description ''On the southwest coast of Gozo, the promontory of Ras il-Wardija holds a Punic-Roman sanctuary. Carved crosses on its walls suggest it later became a Christian place of worship.'' restored on Ras il-Wardija', '6b7a644ac63d2615eae0d0c04ff8b958d05d60b5f464d873795372da79601e12|685b3a6049dffe1cf1f9d546c49bcb87419073e233845541d4eba9bafc263c4f|685b3a6049dffe1cf1f9d546c49bcb87419073e233845541d4eba9bafc263c4f', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Carved crosses on the walls of this headland sanctuary suggest a Christian ending. A religious complex was set up here around the 3rd century BC and stayed in use through the Roman period."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there are carved crosses on the walls [S6]; the site is on a headland [S1]; the site is a sanctuary [S2]; the crosses suggest the site ended as a Christian place of worship [S6]; a religious complex was set up here around the 3rd century BC [S4]; it stayed in use through the Roman period [S5]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "There are carved crosses on the walls of this sanctuary (Ras il-Wardija). [SUPPORTED: https://archives.iccrom.org/oggetti/40536-gozo-ras-il-wardija-mra-mlt-goz-001]; The crosses suggest a Christian ending of the sanctuary''s use. [SUPPORTED: https://archives.iccrom.org/oggetti/40536-gozo-ras-il-wardija-mra-mlt-goz-001]; The site lies on a headland. [SUPPORTED: https://www.archaeopress.com/Archaeopress/DMS/A0D8CA29423E4B9595EC80847C9DFC7C/9781784916695-sample.pdf]; The site is a sanctuary. [SUPPORTED: https://archives.iccrom.org/oggetti/40536-gozo-ras-il-wardija-mra-mlt-goz-001]; A religious complex was set up here around the 3rd century BC. [SUPPORTED: https://www.archaeopress.com/Archaeopress/DMS/A0D8CA29423E4B9595EC80847C9DFC7C/9781784916695-sample.pdf]; The religious complex stayed in use through the Roman period. [SUPPORTED: https://www.archaeopress.com/Archaeopress/DMS/A0D8CA29423E4B9595EC80847C9DFC7C/9781784916695-sample.pdf]"}]'::jsonb),
    ('c9a49774-6211-499c-b80c-9dbeec95b47c'::uuid, 'card_description', 'Unique paintings of a being from Aboriginal myth lie among sandstone cliffs. A heritage register places these images across 230,000 hectares of plateaux and escarpments.', 'Aboriginal rock art dating back 25,000 years depicting Quinkans — mythological spirit beings. The sandstone galleries hold thousands of paintings.', 'teaser-card-s048-rollback:c9a49774-6211-499c-b80c-9dbeec95b47c:card_description', 'rollback of teaser-card-s048: card_description ''Aboriginal rock art dating back 25,000 years depicting Quinkans — mythological spirit beings. The sandstone galleries hold thousands of paintings.'' restored on Quinkan Rock Art', '260ebb591b1e4df5f19b74dc6527ed3e3f66c6067db4611b38d37833596aaf51|dec16781d82b15584f769f03f940afa081ba63803e33c0561de8ce4c9a933e21|dec16781d82b15584f769f03f940afa081ba63803e33c0561de8ce4c9a933e21', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Unique paintings of a being from Aboriginal myth lie among sandstone cliffs. A heritage register places these images across 230,000 hectares of plateaux and escarpments."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site holds paintings [S4]; the rock art is characterised by unique representations of a being from Aboriginal mythology [S1]; it is found among sandstone escarpments [S1]; a heritage register entry describes it as spread across 230,000 hectares [S3]; that area is of plateaux and escarpments [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Paintings of a being from Aboriginal myth (the Quinkan spirit beings) are found here (Quinkan rock art). [SUPPORTED: https://blog.qm.qld.gov.au/2026/09/16/the-stories-written-in-stone-discovering-laura-rock-art/]; These paintings are unique. [SUPPORTED: https://blog.qm.qld.gov.au/2026/09/16/the-stories-written-in-stone-discovering-laura-rock-art/]; The paintings lie among sandstone cliffs. [SUPPORTED: https://blog.qm.qld.gov.au/2026/09/16/the-stories-written-in-stone-discovering-laura-rock-art/]; A heritage register places these images across 230,000 hectares. [SUPPORTED: https://www.environment.gov.au/cgi-bin/ahdb/search.pl?mode=place_detail;place_id=9089]; The register describes this area as plateaux and escarpments. [SUPPORTED: https://www.environment.gov.au/cgi-bin/ahdb/search.pl?mode=place_detail;place_id=9089]"}]'::jsonb),
    ('ce34d01c-2590-4713-b2f3-d2f088307e71'::uuid, 'card_description', 'Herders of mostly sheep and goats likely wintered at this Bronze Age site. It sits on foothill steppes above a river, and over time burials changed from stone box graves to mounds.', 'Occupied from 2460 BC, transhumant pastoralists wintered here in the piedmont steppes, herding sheep and goats. Their burials shifted from cist graves to kurgans over the centuries.', 'teaser-card-s048-rollback:ce34d01c-2590-4713-b2f3-d2f088307e71:card_description', 'rollback of teaser-card-s048: card_description ''Occupied from 2460 BC, transhumant pastoralists wintered here in the piedmont steppes, herding sheep and goats. Their burials shifted from cist graves to kurgans over the centuries.'' restored on Begash', 'f5afc56952e61c893ab101cb3fd695b68fb6ad5baa8d6d60cab77d8d1dcc4fb3|5dfefe5e5745547d195ccf8087659161c7538417112e04d35e45dad0ea34b3ea|5dfefe5e5745547d195ccf8087659161c7538417112e04d35e45dad0ea34b3ea', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Herders of mostly sheep and goats likely wintered at this Bronze Age site. It sits on foothill steppes above a river, and over time burials changed from stone box graves to mounds."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "herders occupied the site [S2]; they mainly herded sheep and goats [S2]; they likely used the site in winter [S2]; it is a Bronze Age site [S1]; it lies on foothill (piedmont) steppes [S2]; it lies above a river [S2]; over time burials changed from stone box (cist) graves to mound (kurgan) burials [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Herders likely wintered at this site [SUPPORTED: https://pbdb.org/?a=samplePage&sample_no=4014]; The herders kept mostly sheep and goats [SUPPORTED: https://factsanddetails.com/asian/cat65/sub422/entry-5237.html]; It is a Bronze Age site [SUPPORTED: https://pbdb.org/?a=samplePage&sample_no=4014]; It sits on foothill steppes [SUPPORTED: https://saielab.wustl.edu/all-projects/burial-excavation-at-begash]; It sits above a river [SUPPORTED: https://saielab.wustl.edu/all-projects/burial-excavation-at-begash]; Burials were at first stone box graves [SUPPORTED: https://saielab.wustl.edu/all-projects/burial-excavation-at-begash]; Over time burials changed from stone box graves to mounds [SUPPORTED: https://saielab.wustl.edu/all-projects/burial-excavation-at-begash]; Mounds came later than the stone box graves [SUPPORTED: https://saielab.wustl.edu/all-projects/burial-excavation-at-begash]"}]'::jsonb),
    ('d013bd60-0008-4319-85ff-1523f13edf5b'::uuid, 'card_description', 'A survey point sits inside the round burial mound on the summit of this hill. The hill is 212 metres high, and on its western slope stands a stone named after a nearby mine.', 'A round barrow crowns the summit of Trink Hill, 212 metres high near Nancledra, with a trig point set within it, and on the western slope stands a stone named after the nearby Giew Mine.', 'teaser-card-s048-rollback:d013bd60-0008-4319-85ff-1523f13edf5b:card_description', 'rollback of teaser-card-s048: card_description ''A round barrow crowns the summit of Trink Hill, 212 metres high near Nancledra, with a trig point set within it, and on the western slope stands a stone named after the nearby Giew Mine.'' restored on Trink Hill', '7b388ea668d0044c437d2874e07fc74e93bf416304b4f448db67a0daec02943d|d51cfa43c3224aebdf22a10ebadaacfc622d7ad166955c4582c7721dc8ddf7a6|d51cfa43c3224aebdf22a10ebadaacfc622d7ad166955c4582c7721dc8ddf7a6', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A survey point sits inside the round burial mound on the summit of this hill. The hill is 212 metres high, and on its western slope stands a stone named after a nearby mine."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a survey (trig) point sits inside the round barrow [S2]; a round burial mound (round barrow) is on the summit [S2]; the site is a hill [S1]; the hill is 212 metres high [S1]; a stone stands on the western slope [S3]; the stone is named after a nearby mine [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A survey point sits inside the round burial mound on the summit of this hill. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=20224]; There is a round burial mound on the summit of this hill. [SUPPORTED: https://www.intocornwall.com/engine/azabout.asp?guide=Trink+Hill]; A survey point is on the summit of this hill. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=20224]; The hill is 212 metres high. [SUPPORTED: https://www.walklakes.co.uk/hill_17596.html]; On its western slope stands a stone. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=6076]; The stone is named after a mine. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=6076]; The mine the stone is named after is nearby. [SUPPORTED: https://www.ancientpenwith.org/menhirs/queriedmenhirs-morvah-towednack.html]"}]'::jsonb),
    ('d2b862c0-44e2-422f-9c17-5548b3c74a7f'::uuid, 'card_description', 'A housing estate was being built when this Roman villa came to light again. The villa keeps original mosaic floors, underfloor heating and the only Roman bath suite visible in its city.', 'Rediscovered in November 1947 as a housing estate went up, Kings Weston Roman Villa retains its original mosaic floors, a hypocaust and the only Roman bath suite visible in Bristol.', 'teaser-card-s048-rollback:d2b862c0-44e2-422f-9c17-5548b3c74a7f:card_description', 'rollback of teaser-card-s048: card_description ''Rediscovered in November 1947 as a housing estate went up, Kings Weston Roman Villa retains its original mosaic floors, a hypocaust and the only Roman bath suite visible in Bristol.'' restored on Kings Weston Roman Villa', '0d539e9ae1f7544a389f85ae6a11632a15ff18e86a35af082446cd50acdb5458|77fe88bd452953f95fd7c3c51cb3ba6a55821645fca445c2b6348536270a5847|77fe88bd452953f95fd7c3c51cb3ba6a55821645fca445c2b6348536270a5847', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A housing estate was being built when this Roman villa came to light again. The villa keeps original mosaic floors, underfloor heating and the only Roman bath suite visible in its city."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the villa was rediscovered [S5]; this happened during construction of a housing estate [S5]; the site is a Roman villa [S2]; it retains original mosaic floors [S3]; it retains underfloor heating (a hypocaust system) [S3]; it has the only Roman bath suite visible in its city [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A housing estate was being built when this Roman villa came to light again. [SUPPORTED: https://bristolandavonarchaeology.org.uk/upcoming-events/field-visit-kingsweston-roman-villa/]; The site is a Roman villa. [SUPPORTED: https://www.kwag.org.uk/2025/10/05/roman-revelations-archaeology-survey-uncovers-new-discoveries/]; The villa had been lost from view before it came to light again. [SUPPORTED: https://www.kwag.org.uk/2025/10/05/roman-revelations-archaeology-survey-uncovers-new-discoveries/]; The villa keeps original mosaic floors. [SUPPORTED: https://bristolandavonarchaeology.org.uk/upcoming-events/field-visit-kingsweston-roman-villa/]; The villa keeps underfloor heating. [SUPPORTED: https://bristolandavonarchaeology.org.uk/upcoming-events/field-visit-kingsweston-roman-villa/]; The villa keeps a Roman bath suite. [SUPPORTED: https://www.kwag.org.uk/2025/10/05/roman-revelations-archaeology-survey-uncovers-new-discoveries/]; It is the only Roman bath suite visible in its city. [SUPPORTED: https://bristolandavonarchaeology.org.uk/upcoming-events/field-visit-kingsweston-roman-villa/]"}]'::jsonb),
    ('d3da22e7-2499-4573-80f1-32037b641d57'::uuid, 'card_description', 'Royalist soldiers in the Civil War set guns on part of this Roman earthwork. Two parallel banks, up to 20 metres apart, flank a dug channel, and a stretch 110 metres long survives.', 'Raw Dykes in Leicester: two parallel Roman banks with a channel between, once at least 550 metres long, now 110 metres. In the English Civil War, Royalists set artillery on part of it.', 'teaser-card-s048-rollback:d3da22e7-2499-4573-80f1-32037b641d57:card_description', 'rollback of teaser-card-s048: card_description ''Raw Dykes in Leicester: two parallel Roman banks with a channel between, once at least 550 metres long, now 110 metres. In the English Civil War, Royalists set artillery on part of it.'' restored on Raw Dykes', '79c130c5813cffddcd88d9c7efc422248bf35c1c6977e87752e3cbdb2ae87504|d4f0b6016518469e5c7ea3d14be01fca7c071eea589c3af1bd274b53e2fcefc2|d4f0b6016518469e5c7ea3d14be01fca7c071eea589c3af1bd274b53e2fcefc2', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Royalist soldiers in the Civil War set guns on part of this Roman earthwork. Two parallel banks, up to 20 metres apart, flank a dug channel, and a stretch 110 metres long survives."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Royalist soldiers used part of the earthwork as an artillery emplacement [S5]; this was during the Civil War [S5]; it is a Roman earthwork [S1]; it has two parallel banks [S2]; the banks are up to 20 metres apart [S2]; a dug (excavated) channel runs between them [S2]; a stretch 110 metres long survives [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Royalist soldiers in the Civil War set guns on part of this Roman earthwork. [SUPPORTED: https://bcw-project.org.uk/military/english-civil-war/midlands-and-east/the-naseby-campaign]; The site is a Roman earthwork. [SUPPORTED: https://romanroads.org/external/mitchell_canal_research.pdf]; The soldiers who set guns on it were Royalist. [SUPPORTED: https://www.storyofleicester.info/a-place-to-live/the-raw-dykes/]; The guns were set on it in the Civil War. [SUPPORTED: https://www.storyofleicester.info/a-place-to-live/the-raw-dykes/]; The earthwork has two parallel banks. [SUPPORTED: https://romanroads.org/external/mitchell_canal_research.pdf]; The banks are up to 20 metres apart. [SUPPORTED: https://romanroads.org/external/mitchell_canal_research.pdf]; The banks flank a dug channel. [SUPPORTED: https://www.storyofleicester.info/a-place-to-live/the-raw-dykes/]; A stretch 110 metres long survives. [SUPPORTED: https://www.storyofleicester.info/a-place-to-live/the-raw-dykes/]"}]'::jsonb),
    ('d765c593-eb36-4978-b73f-534333b85bda'::uuid, 'card_description', 'Glazed pottery and fine imported ceramics turned up in digs at this earth platform. The finds date from the 16th to 18th centuries, and a house with wood walls was built on the platform.', 'In Lima''s San Miguel District, Huaca Casa Rosada rises as a platform of rammed earth and adobe, approximately 36 meters on each side, that became the base of a Republican-period house.', 'teaser-card-s048-rollback:d765c593-eb36-4978-b73f-534333b85bda:card_description', 'rollback of teaser-card-s048: card_description "In Lima''s San Miguel District, Huaca Casa Rosada rises as a platform of rammed earth and adobe, approximately 36 meters on each side, that became the base of a Republican-period house." restored on Huaca Casa Rosada', '976d6086bbc548f3fde8eb0de573e79d3cda353f088ae8548114250078216b14|2e8684d7d032c8edc00014f03a36248a02d5dbace08c4658ccc23a8f2fb3832c|2e8684d7d032c8edc00014f03a36248a02d5dbace08c4658ccc23a8f2fb3832c', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Glazed pottery and fine imported ceramics turned up in digs at this earth platform. The finds date from the 16th to 18th centuries, and a house with wood walls was built on the platform."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "glazed pottery was found in excavations here [S5]; fine imported ceramics were found in excavations here [S5]; the site is a platform of earth (rammed earth and adobe) [S3]; the finds date from the 16th to 18th centuries [S5]; a house with wood walls was built on the platform [S4, S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A house with wood walls was built on the platform. [SUPPORTED: https://es.wikipedia.org/wiki/Huaca_Casa_Rosada]; Digs (archaeological excavations) took place at this site. [SUPPORTED: https://revistas.pucp.edu.pe/index.php/boletindearqueologia/article/download/19342/19465/0]; Glazed pottery turned up in the digs. [SUPPORTED: https://link.springer.com/rwe/10.1007/978-3-030-30018-0_3312]; Fine imported ceramics turned up in the digs. [SUPPORTED: https://es.wikipedia.org/wiki/Huaca_Casa_Rosada]; The site is an earth platform. [SUPPORTED: https://es.wikipedia.org/wiki/Huaca_Casa_Rosada]; The finds date from the 16th to 18th centuries. [SUPPORTED: https://es.wikipedia.org/wiki/Huaca_Casa_Rosada]"}]'::jsonb),
    ('d799bb0f-8ffd-4a29-a516-ffd445f6b699'::uuid, 'card_description', 'Excavators uncovered 154 individual graves at this burial site. The burials held many grave goods, mainly jewellery and weapons, and 22 previously unknown structures turned up as well.', 'Found in 2019 near Overstone, the Overstone Anglo-Saxon Cemetery held 154 graves, 3000 artefacts and 22 previously unknown structures, its burials rich in jewellery and weapons.', 'teaser-card-s048-rollback:d799bb0f-8ffd-4a29-a516-ffd445f6b699:card_description', 'rollback of teaser-card-s048: card_description ''Found in 2019 near Overstone, the Overstone Anglo-Saxon Cemetery held 154 graves, 3000 artefacts and 22 previously unknown structures, its burials rich in jewellery and weapons.'' restored on Overstone Anglo-Saxon Cemetery', 'cc70f4b62d17e66e8054b76f96b8dfe68ab9033274105e8860219680807fcb20|0dcaf96cee101c4b171a6c747a5f413581f838c3718c165ce48ed466f410e9fa|0dcaf96cee101c4b171a6c747a5f413581f838c3718c165ce48ed466f410e9fa', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Excavators uncovered 154 individual graves at this burial site. The burials held many grave goods, mainly jewellery and weapons, and 22 previously unknown structures turned up as well."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "it is a burial site [S1]; excavators uncovered 154 individual graves [S5]; the burials held many grave goods [S6]; the grave goods were mainly jewellery and weapons [S6]; 22 previously unknown structures were also found at the site [S7]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Excavators uncovered 154 individual graves at this site. [SUPPORTED: https://her.northamptonshire.gov.uk/Monument/MNN161260]; The site is a burial site. [SUPPORTED: https://her.northamptonshire.gov.uk/Monument/MNN161260]; The burials held many grave goods. [SUPPORTED: https://her.northamptonshire.gov.uk/Monument/MNN161260]; The grave goods were mainly jewellery. [SUPPORTED: https://archaeology.co.uk/articles/news/northamptonshires-largest-anglo-saxon-cemetery-discovered.htm]; Weapons were the other main kind of grave goods. [SUPPORTED: https://archaeology.co.uk/articles/news/northamptonshires-largest-anglo-saxon-cemetery-discovered.htm]; 22 previously unknown structures turned up as well. [SUPPORTED: https://archaeology.co.uk/articles/news/northamptonshires-largest-anglo-saxon-cemetery-discovered.htm]"}]'::jsonb),
    ('da2f5fea-80b2-4c88-a5d1-738c054512b5'::uuid, 'card_description', 'Half of a hominin jawbone lay 1.5 m below the layer that held artifacts. The other cave of the complex holds remains that record the shift from the Lower to the Middle Paleolithic.', 'In 2006 the Balanica caves gave up half a hominin jaw, the first hominin specimen in the Central Balkans recovered through controlled excavations with firm stratigraphic context.', 'teaser-card-s048-rollback:da2f5fea-80b2-4c88-a5d1-738c054512b5:card_description', 'rollback of teaser-card-s048: card_description ''In 2006 the Balanica caves gave up half a hominin jaw, the first hominin specimen in the Central Balkans recovered through controlled excavations with firm stratigraphic context.'' restored on Balanica', '94c202aa9a6d6a3c2ef54758e01a9956cd87938135009df02ab8cccdd16c0265|82723c73a750635ad08926c0789948769ba5791689217157bb97fb23ecf85c36|82723c73a750635ad08926c0789948769ba5791689217157bb97fb23ecf85c36', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-018", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Half of a hominin jawbone lay 1.5 m below the layer that held artifacts. The other cave of the complex holds remains that record the shift from the Lower to the Middle Paleolithic."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "half of a hominin jawbone (a hemi-mandible) was found at the site [S5]; it lay 1.5 m below the artifact-bearing layer [S6]; the site is a complex of caves, with another cave besides the one of the jawbone [S1, S2, S5]; the other cave holds remains that record the transition from the Lower to the Middle Paleolithic [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Half of a hominin jawbone was found at this site. [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0054608]; The jawbone lay 1.5 m below the layer that held artifacts. [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0054608]; The site is a complex of caves, with one other cave besides the one that held the jawbone. [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0054608]; The other cave of the complex holds remains that record the shift from the Lower to the Middle Paleolithic. [SUPPORTED: https://link.springer.com/article/10.1007/s10963-023-09179-1]"}]'::jsonb),
    ('dde240ca-5969-4123-a842-e7e235f7566b'::uuid, 'card_description', 'Before mining destroyed the valley, surveys helped recover its largest settlements. Digs found traces of 160 houses from eight settlements, three enclosures and a cemetery of early farmers.', 'In the Merzbach Valley, Langweiler revealed 160 houses, enclosures and a cemetery of the earliest farming societies in west-central Europe, from 5300-4900 BC, before mining destroyed it.', 'teaser-card-s048-rollback:dde240ca-5969-4123-a842-e7e235f7566b:card_description', 'rollback of teaser-card-s048: card_description ''In the Merzbach Valley, Langweiler revealed 160 houses, enclosures and a cemetery of the earliest farming societies in west-central Europe, from 5300-4900 BC, before mining destroyed it.'' restored on Langweiler - Archaeological Site', '39d9f462a18ce363c5edf88285725c8d4389c9c18315186d5f22e5b53ef76a80|170a9da5a47b28b807f52e2749a846f3b80961f3732eca257fb7dacca007b9ce|170a9da5a47b28b807f52e2749a846f3b80961f3732eca257fb7dacca007b9ce', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Before mining destroyed the valley, surveys helped recover its largest settlements. Digs found traces of 160 houses from eight settlements, three enclosures and a cemetery of early farmers."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "mining destroyed the area of the valley [S4]; surveys contributed to recovering the valley''s largest settlements before that destruction [S4]; excavations revealed evidence of 160 houses [S2]; the houses come from eight settlement sites [S2]; three enclosures were found [S2]; a cemetery was found [S2]; these belonged to early farming societies [S3, S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Digs found traces of 160 houses from eight settlements, three enclosures and a cemetery of early farmers [SUPPORTED: https://journals.ed.ac.uk/lithicstudies/article/download/4444/8829/21302]; Digs found traces of 160 houses [SUPPORTED: https://journals.ed.ac.uk/lithicstudies/article/download/4444/8829/21302]; The houses came from eight settlements [SUPPORTED: https://journals.ed.ac.uk/lithicstudies/article/download/4444/8829/21302]; Digs found three enclosures [SUPPORTED: https://journals.ed.ac.uk/lithicstudies/article/download/4444/8829/21302]; Digs found a cemetery [SUPPORTED: https://de.wikipedia.org/wiki/Gr%C3%A4berfeld]; The houses, settlements, enclosures and cemetery were those of early farmers [SUPPORTED: https://journals.ed.ac.uk/lithicstudies/article/download/4444/8829/21302]; Mining destroyed the valley [SUPPORTED: https://de.wikipedia.org/wiki/Langweiler_8]; Before mining destroyed the valley, surveys helped recover its largest settlements [SUPPORTED: https://scholarlypublications.universiteitleiden.nl/download/1887/28075/1?col=81522199050002711]"}]'::jsonb),
    ('e282f2a0-5fbd-445b-81dc-63432936feff'::uuid, 'card_description', 'A chain of ponds hides among rocks at the foot of a steep hill. Rushes surround the water, and rock paintings on the slopes beside it show the ponds have been used for thousands of years.', 'At the foot of Amazmaz, on the Adrar plateau, a chain of ponds hides among rocks and rushes, and rock paintings on the slopes show the waters were used for thousands of years.', 'teaser-card-s048-rollback:e282f2a0-5fbd-445b-81dc-63432936feff:card_description', 'rollback of teaser-card-s048: card_description ''At the foot of Amazmaz, on the Adrar plateau, a chain of ponds hides among rocks and rushes, and rock paintings on the slopes show the waters were used for thousands of years.'' restored on Amazmaz', '4e999ed23ccc39baf64f7fb458c70ee17f9d358b609931134d1e34a78ce1a0eb|7fc2cb2ab1c7c39e4e8aceb3e0049b0cfcdcb024e71816112ff42dadd5819491|7fc2cb2ab1c7c39e4e8aceb3e0049b0cfcdcb024e71816112ff42dadd5819491', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-018", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A chain of ponds hides among rocks at the foot of a steep hill. Rushes surround the water, and rock paintings on the slopes beside it show the ponds have been used for thousands of years."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there is a chain of ponds [S2]; the ponds are hidden among rocks [S2]; the ponds lie at the foot of a hill [S2]; the hill is steep [S1]; rushes surround the water [S2]; there are rock paintings on the slopes beside the water [S2]; the paintings show the ponds have been used for thousands of years [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A chain of ponds hides among rocks at the foot of a steep hill [SUPPORTED: https://prehistoireouestsaharienne.wordpress.com/2020/05/30/les-peintures-rupestres-de-ladrar-de-mauritanie-ii-autres-stations/]; The ponds form a chain: there are several of them [SUPPORTED: https://www.point-afrique.com/destinations/adrar-mauritanien/]; The ponds hide among rocks [SUPPORTED: https://www.amatlichtours.mr/en/our-tours/]; The ponds are at the foot of a steep hill [SUPPORTED: https://fr.wikipedia.org/wiki/Amazmaz]; Rushes surround the water [SUPPORTED: https://www.amatlichtours.mr/en/our-tours/]; Rock paintings are on the slopes beside the water [SUPPORTED: https://prehistoireouestsaharienne.wordpress.com/2020/05/30/les-peintures-rupestres-de-ladrar-de-mauritanie-ii-autres-stations/]; The rock paintings show the ponds have been used for thousands of years [SUPPORTED: https://www.amatlichtours.mr/en/our-tours/]"}]'::jsonb),
    ('e5e74a71-b666-42a3-917b-cec6e80c81ca'::uuid, 'card_description', 'The grandson of a tyrant set up this altar while he held office. People came to the altar to plead and seek refuge, and its exact spot, which no ancient source gives, was found by digging.', 'In the Classical Agora of Athens stood the Altar of the Twelve Gods, a place of supplication and refuge and, from at least the 5th century BC, the zero point for distances to Athens.', 'teaser-card-s048-rollback:e5e74a71-b666-42a3-917b-cec6e80c81ca:card_description', 'rollback of teaser-card-s048: card_description ''In the Classical Agora of Athens stood the Altar of the Twelve Gods, a place of supplication and refuge and, from at least the 5th century BC, the zero point for distances to Athens.'' restored on Altar of the Twelve Gods', 'f7336644217e4e1d764d481907b8ed373f019687089afd6316e76916ad515a54|b4dd91ae1ed6f68a7180c5d0d9ed7c51f83ff9cbfc274e0a226d1940003b6a4d|b4dd91ae1ed6f68a7180c5d0d9ed7c51f83ff9cbfc274e0a226d1940003b6a4d', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-018", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The grandson of a tyrant set up this altar while he held office. People came to the altar to plead and seek refuge, and its exact spot, which no ancient source gives, was found by digging."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the altar was set up by the grandson of a tyrant [S2]; he set it up while he held office (as archon) [S2]; people came to the altar to plead (supplication) [S5]; people came to the altar to seek refuge [S5]; no ancient source gives its exact spot [S6]; its exact spot was found by excavation [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The grandson of a tyrant set up this altar while he held office [SUPPORTED: https://en.wikisource.org/wiki/History_of_the_Peloponnesian_War/Book_6]; The man who set up the altar was the grandson of a tyrant [SUPPORTED: https://en.wikipedia.org/wiki/Twelve_Olympians]; He set up the altar while he held office [SUPPORTED: https://en.wikisource.org/wiki/History_of_the_Peloponnesian_War/Book_6]; People came to the altar to plead [SUPPORTED: https://en.wikisource.org/wiki/The_History_of_Herodotus_(Macaulay)/Book_VI]; People came to the altar to seek refuge [SUPPORTED: https://en.wikipedia.org/wiki/Callistratus_of_Aphidnae]; No ancient source gives the altar''s exact spot [UNVERIFIABLE, no proving quote: None]; The altar''s exact spot was found by digging [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Agora_of_Athens]"}]'::jsonb),
    ('e732ae7f-cbe5-41a2-a784-90f7731d29f0'::uuid, 'card_description', 'Heraclius sacked this temple in a war with the Sasanians. The sacred flame burned long into the Islamic era, and by the late 10th or early 11th century had most likely gone out.', 'Sasanian kings built the Azargoshnasp Fire Temple for one of the three most sacred fires of pre-Islamic Iran. Heraclius sacked it in 623/4, yet the fire burned on into the Islamic era.', 'teaser-card-s048-rollback:e732ae7f-cbe5-41a2-a784-90f7731d29f0:card_description', 'rollback of teaser-card-s048: card_description ''Sasanian kings built the Azargoshnasp Fire Temple for one of the three most sacred fires of pre-Islamic Iran. Heraclius sacked it in 623/4, yet the fire burned on into the Islamic era.'' restored on Azargoshnasp Fire Temple', 'ec4f3b47bde6f1e368643c81c11a621846c74a3ba95631acf6c7d058407ce34c|b4b1e5a9018127a3fa43b7cf9ffb3c094d72781ebe95c98fdf867df4e968eaf5|b4b1e5a9018127a3fa43b7cf9ffb3c094d72781ebe95c98fdf867df4e968eaf5', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-018", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Heraclius sacked this temple in a war with the Sasanians. The sacred flame burned long into the Islamic era, and by the late 10th or early 11th century had most likely gone out."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Heraclius sacked the temple [S6]; the sack happened in a war with the Sasanians [S6]; the temple held a sacred flame [S1]; the flame burned for a long time into the Islamic era [S7]; by the late 10th or early 11th century the flame had most likely gone out [S7]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Heraclius sacked this temple [SUPPORTED: https://www.kavehfarrokh.com/uncategorized/mary-boyce-adur-gushnasp/]; The sack came in a war with the Sasanians [SUPPORTED: https://en.wikipedia.org/wiki/Byzantine%E2%80%93Sasanian_War_of_602%E2%80%93628]; The temple held a sacred flame [SUPPORTED: https://www.kavehfarrokh.com/uncategorized/mary-boyce-adur-gushnasp/]; The sacred flame burned long into the Islamic era [SUPPORTED: https://www.kavehfarrokh.com/uncategorized/mary-boyce-adur-gushnasp/]; By the late 10th or early 11th century the flame had most likely gone out [SUPPORTED: https://www.kavehfarrokh.com/uncategorized/mary-boyce-adur-gushnasp/]"}]'::jsonb),
    ('ec7f3fd8-9328-4a69-bf84-594f4fc2aa2a'::uuid, 'card_description', 'John Garstang uncovered steps into an underground chamber here in 1903. The chamber had stone walls and lay below the command building of a Roman fort begun around 80 CE in timber.', 'Above a tight bend of the River Noe, Navio Roman Fort guarded the Doctor''s Gate route. Excavations in 1903 uncovered steps down to an underground stone-walled chamber below its headquarters.', 'teaser-card-s048-rollback:ec7f3fd8-9328-4a69-bf84-594f4fc2aa2a:card_description', 'rollback of teaser-card-s048: card_description "Above a tight bend of the River Noe, Navio Roman Fort guarded the Doctor''s Gate route. Excavations in 1903 uncovered steps down to an underground stone-walled chamber below its headquarters." restored on Navio Roman Fort', '80ccc0c067901c3bf61531824361775dbaed75ace783ec81db5b79dd9bd7e746|c29b89ab9922e1fd64c0b2cb63d73ad6b07f0a9fe4a6d13eb9f4b3070917f101|c29b89ab9922e1fd64c0b2cb63d73ad6b07f0a9fe4a6d13eb9f4b3070917f101', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "John Garstang uncovered steps into an underground chamber here in 1903. The chamber had stone walls and lay below the command building of a Roman fort begun around 80 CE in timber."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-009 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "John Garstang uncovered steps at the site [S6]; the steps led into an underground chamber [S6]; he uncovered them in 1903 [S6]; the chamber had stone walls [S6]; the chamber lay below the command (headquarters) building [S6]; the site is a Roman fort [S1]; the fort was begun around 80 CE [S3]; the first fort was built in timber [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "John Garstang uncovered an underground chamber here in 1903 [SUPPORTED: https://dokumen.pub/navio-the-fort-and-vicus-at-brough-on-noe-derbyshire-9780860547594-9781407318608.html]; Steps led into the chamber (Garstang uncovered steps into it) [SUPPORTED: https://dokumen.pub/navio-the-fort-and-vicus-at-brough-on-noe-derbyshire-9780860547594-9781407318608.html]; The chamber was underground [SUPPORTED: https://dokumen.pub/navio-the-fort-and-vicus-at-brough-on-noe-derbyshire-9780860547594-9781407318608.html]; The chamber had stone walls [SUPPORTED: https://dokumen.pub/navio-the-fort-and-vicus-at-brough-on-noe-derbyshire-9780860547594-9781407318608.html]; The chamber lay below the command building of the fort [SUPPORTED: https://dokumen.pub/navio-the-fort-and-vicus-at-brough-on-noe-derbyshire-9780860547594-9781407318608.html]; The site is a Roman fort [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR2311]; The fort was begun around 80 CE [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR2311]; The fort was begun in timber [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR2311]"}]'::jsonb),
    ('f1e8a463-b2c4-42c2-a0b8-94e7bf420f6a'::uuid, 'card_description', 'A two-sided relief shows a bull slain on one side, a ritual meal on the other. The gray limestone carving comes from a temple to the sun god Mithra, atypical for its floor at ground level.', 'By the river Trešanica stood the Konjic Mithraeum, an early 4th century AD temple to Mithra. Its gray limestone relief shows a Tauroctony on one side and a ritual meal on the other.', 'teaser-card-s048-rollback:f1e8a463-b2c4-42c2-a0b8-94e7bf420f6a:card_description', 'rollback of teaser-card-s048: card_description ''By the river Trešanica stood the Konjic Mithraeum, an early 4th century AD temple to Mithra. Its gray limestone relief shows a Tauroctony on one side and a ritual meal on the other.'' restored on Konjic Mithraeum', '4cd863288c5c3ca4b68f79d5100712ac3a515567af80352b0b8acf7836030f88|195c0326de5cfe7f17e00f9eaae67ae8b18ab81aa0a2f27aea7b388c957e13a8|195c0326de5cfe7f17e00f9eaae67ae8b18ab81aa0a2f27aea7b388c957e13a8', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A two-sided relief shows a bull slain on one side, a ritual meal on the other. The gray limestone carving comes from a temple to the sun god Mithra, atypical for its floor at ground level."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-010 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there is a relief that is two-sided [S4]; one side shows the slaying of a bull (the tauroctony) [S4]; the other side shows a ritual meal [S4]; the relief is carved in gray limestone [S4]; the relief belongs to this temple of the Mithras cult [S1, S4]; the site is a temple dedicated to the sun god Mithra [S1]; the site is atypical because its floor is at ground level [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A two-sided relief shows a bull slain on one side, a ritual meal on the other [SUPPORTED: https://www.mithraeum.eu/monument/259]; The relief is two-sided [SUPPORTED: https://mithras.tertullian.org/display.php?page=cimrm1896]; One side shows a bull slain [SUPPORTED: https://mithras.tertullian.org/display.php?page=cimrm1896]; The other side shows a ritual meal [SUPPORTED: https://mithras.tertullian.org/display.php?page=cimrm1896]; The carving is of gray limestone [SUPPORTED: https://mithras.tertullian.org/display.php?page=cimrm1896]; The carving comes from a temple of Mithra [SUPPORTED: https://marjanhajnal.wordpress.com/2014/02/01/hram-boga-mitre-u-konjicu-kult-boga-mithrasa-znacaj-i-karakteristike-mirjana-kapetanovic/]; Mithra, to whom the temple was dedicated, is the sun god [SUPPORTED: https://mithras.tertullian.org/display.php?page=cimrm1896]; The temple is atypical for its floor at ground level [SUPPORTED: https://marjanhajnal.wordpress.com/2014/02/01/hram-boga-mitre-u-konjicu-kult-boga-mithrasa-znacaj-i-karakteristike-mirjana-kapetanovic/]"}]'::jsonb),
    ('f2041141-c82a-4e04-a6e6-d7d2e29f4ea5'::uuid, 'card_description', 'Moved away after its dig, this Neolithic stone tomb came back in 2021. In the late Bronze Age or early Iron Age, the Funnelbeaker grave was used once more as a burial site.', 'A Neolithic burial of the Funnelbeaker culture, the Schalkholz Passage Grave was archaeologically investigated in 1969 and 1970, then moved to Heide. In 2021 it went back to Schalkholz.', 'teaser-card-s048-rollback:f2041141-c82a-4e04-a6e6-d7d2e29f4ea5:card_description', 'rollback of teaser-card-s048: card_description ''A Neolithic burial of the Funnelbeaker culture, the Schalkholz Passage Grave was archaeologically investigated in 1969 and 1970, then moved to Heide. In 2021 it went back to Schalkholz.'' restored on Schalkholz Passage Grave', '697f45c5357f88a7cc5a23be7c83d73ea0cb7ff694b8f2d4ab13598896c39e9f|1f4de06ef5981f2c1afbaaa431e658e7748b4ff239d3ed46016e520dd2186f95|1f4de06ef5981f2c1afbaaa431e658e7748b4ff239d3ed46016e520dd2186f95', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Moved away after its dig, this Neolithic stone tomb came back in 2021. In the late Bronze Age or early Iron Age, the Funnelbeaker grave was used once more as a burial site."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-010 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the tomb was archaeologically investigated (a dig) [S4]; after that investigation it was moved away [S4]; it was moved back in 2021 [S5]; it is Neolithic [S1]; it is a stone (megalithic) tomb [S1]; it is a grave of the Funnelbeaker culture [S1]; in the late Bronze Age or early Iron Age it was used again as a burial site [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Moved away after its dig, this Neolithic stone tomb came back in 2021. [SUPPORTED: https://www.echt-dithmarschen.de/typisch/poi/ganggrab-von-schalkholz/]; The tomb had a dig (it was excavated). [SUPPORTED: https://schalkholz.de/freizeit-und-tourismus/steinkammergrab-schalkholz.html]; It was moved away after its dig. [SUPPORTED: https://schalkholz.de/freizeit-und-tourismus/steinkammergrab-schalkholz.html]; It came back in 2021. [SUPPORTED: https://schalkholz.de/freizeit-und-tourismus/steinkammergrab-schalkholz.html]; The tomb is Neolithic. [SUPPORTED: https://www.boyens-medien.de/artikel/lokales/tonnenschwerer-granit-am-haken-388905.html]; It is a stone tomb. [SUPPORTED: https://www.boyens-medien.de/artikel/lokales/tonnenschwerer-granit-am-haken-388905.html]; It is a Funnelbeaker grave. [SUPPORTED: https://www.echt-dithmarschen.de/typisch/poi/ganggrab-von-schalkholz/]; The grave was used once more as a burial site. [SUPPORTED: https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Schalkholz-Vierth]; That later use was in the late Bronze Age or early Iron Age. [SUPPORTED: https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Schalkholz-Vierth]"}]'::jsonb),
    ('f284934a-a5b3-4c85-ba90-953aa9e72bc5'::uuid, 'card_description', 'Seats of honour with stone backs sit in the north part of the orchestra. The small theatre dates from the 4th-3rd century BC, and may have doubled as a council house.', '300 BC theatre of one of the most important cities of ancient Aetolia, set on the hills of Adirion on the eastern side of the ancient city, looking out across the plain below.', 'teaser-card-s048-rollback:f284934a-a5b3-4c85-ba90-953aa9e72bc5:card_description', 'rollback of teaser-card-s048: card_description ''300 BC theatre of one of the most important cities of ancient Aetolia, set on the hills of Adirion on the eastern side of the ancient city, looking out across the plain below.'' restored on Ancient Theatre of Makyneia', '381472819737d09ab69b652ff741801661bfbe893dd6d35d91d5d6cfc8e1bd46|561a4efabe16eaa1a4220dfb8cbf566c8826af416491dd400147c30cc32e61c4|561a4efabe16eaa1a4220dfb8cbf566c8826af416491dd400147c30cc32e61c4', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-019", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Seats of honour with stone backs sit in the north part of the orchestra. The small theatre dates from the 4th-3rd century BC, and may have doubled as a council house."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there are seats of honour [S3]; the seats of honour have stone backs [S3]; they are in the north part of the orchestra [S3]; the site is a small theatre [S1]; it dates from the 4th-3rd century BC [S1]; it may have doubled as a council house [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Seats of honour sit in the north part of the orchestra [SUPPORTED: https://diazoma.gr/en/theaters/theatre-of-macynia/]; The seats of honour have stone backs [SUPPORTED: https://diazoma.gr/en/theaters/theatre-of-macynia/]; The site is a theatre [SUPPORTED: https://www.efaaitl.gr/arch_sites/%CE%B1%CF%81%CF%87%CE%B1%CE%B9%CE%B1-%CE%BC%CE%B1%CE%BA%CF%85%CE%BD%CE%B5%CE%B9%CE%B1/]; The theatre is small [SUPPORTED: https://diazoma.gr/en/theaters/theatre-of-macynia/]; The theatre dates from the 4th-3rd century BC [SUPPORTED: https://api.crossref.org/works/10.3390/metrology2030023]; The theatre may have doubled as a council house [SUPPORTED: https://www.efaaitl.gr/arch_sites/%CE%B1%CF%81%CF%87%CE%B1%CE%B9%CE%B1-%CE%BC%CE%B1%CE%BA%CF%85%CE%BD%CE%B5%CE%B9%CE%B1/]"}]'::jsonb),
    ('f4931c71-9e14-4bdc-ad9d-88bf763b6985'::uuid, 'card_description', 'The oldest human droppings then known were found at this rock shelter in 2014. They showed that Neanderthal diets included plants, and the shelter sits at the foot of a high limestone wall.', 'Beneath a limestone wall 38 meters high, Neanderthals at El Salt left fire pits, flint tools and six teeth at least 50,000 years ago, and coprolites showing their diets included plants.', 'teaser-card-s048-rollback:f4931c71-9e14-4bdc-ad9d-88bf763b6985:card_description', 'rollback of teaser-card-s048: card_description ''Beneath a limestone wall 38 meters high, Neanderthals at El Salt left fire pits, flint tools and six teeth at least 50,000 years ago, and coprolites showing their diets included plants.'' restored on El Salt', '61856c999d3debdd0c5fee1c698be7b92dac3d8a7cb944c6cd0926d71615373f|918e24d2d93f1823690ba1a7ffdd0fb8dc399124159bea07c8c694132dc76e39|918e24d2d93f1823690ba1a7ffdd0fb8dc399124159bea07c8c694132dc76e39', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The oldest human droppings then known were found at this rock shelter in 2014. They showed that Neanderthal diets included plants, and the shelter sits at the foot of a high limestone wall."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-005 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the then-oldest known human droppings (coprolites) were found at the site [S3]; they were found in 2014 [S3]; the site is a rock shelter [S5]; they showed that Neanderthal diets included plants [S3]; the shelter lies at the foot of a high limestone wall [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The oldest human droppings then known were found at this site [SUPPORTED: https://www.nature.com/articles/s42003-021-01689-y]; The droppings were found in 2014 [UNVERIFIABLE, no proving quote: None]; The site is a rock shelter [SUPPORTED: https://link.springer.com/article/10.1007/s12520-023-01787-4]; The droppings were left by Neanderthals [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0101045]; They showed that Neanderthal diets included plants [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0101045]; The shelter sits at the foot of a high limestone wall [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0214955]"}]'::jsonb),
    ('f56eb08e-29e1-42dc-b238-4867b12ba88b'::uuid, 'card_description', 'The body laid in this Neolithic tomb was not cremated, analyses showed. The tomb''s single rectangular chamber, about 2.75 meters long, sits on a high point completely ringed by woods.', 'Surrounded by woods on a rise near Saint-Aquilin in the Dordogne, Peyre-Brune is a Neolithic dolmen: one rectangular chamber, the burial tomb of a local chieftain who was not incinerated.', 'teaser-card-s048-rollback:f56eb08e-29e1-42dc-b238-4867b12ba88b:card_description', 'rollback of teaser-card-s048: card_description ''Surrounded by woods on a rise near Saint-Aquilin in the Dordogne, Peyre-Brune is a Neolithic dolmen: one rectangular chamber, the burial tomb of a local chieftain who was not incinerated.'' restored on Peyre-Brune', '0992958a338d5e02f2ef58d8411786d375b94960f7a60af5c8b3ea5903d37c7c|83c2aa5a441acc10bf69df1094aba8e0e676807413ba5fb820752781f37db96b|83c2aa5a441acc10bf69df1094aba8e0e676807413ba5fb820752781f37db96b', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The body laid in this Neolithic tomb was not cremated, analyses showed. The tomb''s single rectangular chamber, about 2.75 meters long, sits on a high point completely ringed by woods."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-010 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a body was laid in the tomb [S5, S6]; it is Neolithic [S1]; it is a tomb [S5]; analyses showed that the body was not cremated [S6]; the tomb has a single chamber [S4]; the chamber is rectangular [S4]; it is about 2.75 meters long [S4]; it sits on a high point [S3]; it is completely surrounded by woods [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The body laid in this tomb was not cremated [SUPPORTED: https://archive.org/stream/bulletindelasocieteperigord1/Bulletin_de_la_Societe_Perigord_1_djvu.txt]; Analyses showed that the body was not cremated [SUPPORTED: https://archive.org/stream/bulletindelasocieteperigord1/Bulletin_de_la_Societe_Perigord_1_djvu.txt]; A body was laid in the tomb [SUPPORTED: https://archive.org/stream/bulletindelasocieteperigord1/Bulletin_de_la_Societe_Perigord_1_djvu.txt]; The monument is a tomb [SUPPORTED: https://www.lieux-insolites.fr/dordogne/megadordogne/megadordogne.htm]; The tomb is Neolithic [SUPPORTED: https://www.cirkwi.com/fr/point-interet/2712825-dolmen-de-peyrebrune]; The tomb has a single chamber [SUPPORTED: https://www.cirkwi.com/fr/point-interet/2712825-dolmen-de-peyrebrune]; The chamber is rectangular [SUPPORTED: https://archive.org/stream/bulletindelasocieteperigord1/Bulletin_de_la_Societe_Perigord_1_djvu.txt]; The chamber is about 2.75 meters long [SUPPORTED: https://fr.wikipedia.org/wiki/Dolmen_de_Peyre-Brune]; The tomb sits on a high point [SUPPORTED: https://fr.wikipedia.org/wiki/Dolmen_de_Peyre-Brune]; The high point is completely ringed by woods [SUPPORTED: https://archive.org/stream/bulletindelasocieteperigord1/Bulletin_de_la_Societe_Perigord_1_djvu.txt]"}]'::jsonb),
    ('f5f8472d-d102-48b6-98b3-2d9fcfa53752'::uuid, 'card_description', 'A medieval hunting lodge was built inside this Iron Age hill fort. The lodge''s remains are still visible on the highest point of the Chase, in a fort abandoned as Romans occupied the area.', 'Castle Ring is an Iron Age hill fort, situated high up on the southern edge of Cannock Chase, Staffordshire.', 'teaser-card-s048-rollback:f5f8472d-d102-48b6-98b3-2d9fcfa53752:card_description', 'rollback of teaser-card-s048: card_description ''Castle Ring is an Iron Age hill fort, situated high up on the southern edge of Cannock Chase, Staffordshire.'' restored on Castle Ring', 'e2abe175e379aaeb1a5df29cb3cd4d1d818eb032cebde890f15727775939cc3d|cb16e6fc7d9b0b3a959a0cf5e1db291ef0b1efccc8ec3054f51141c1bdc61429|cb16e6fc7d9b0b3a959a0cf5e1db291ef0b1efccc8ec3054f51141c1bdc61429', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A medieval hunting lodge was built inside this Iron Age hill fort. The lodge''s remains are still visible on the highest point of the Chase, in a fort abandoned as Romans occupied the area."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-010 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a hunting lodge was built inside the fort [S7]; the lodge was built in the medieval period [S7]; the site is an Iron Age hill fort [S1]; the remains of the lodge are still visible [S8]; the site is the highest point of the Chase [S2]; the fort was abandoned [S5]; the abandonment came with the Romans occupying the area [S5]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A medieval hunting lodge was built inside this Iron Age hill fort [SUPPORTED: https://www.cannockchasedc.gov.uk/residents/leisure/countryside-service/castle-ring-scheduled-ancient-monument]; The site is a hill fort [SUPPORTED: https://cannockchase.org.uk/care-for-the-chase/heritage-and-history/castle-ring-hill-fort/]; The hill fort is of the Iron Age [SUPPORTED: https://www.cannockchasedc.gov.uk/residents/leisure/countryside-service/castle-ring-scheduled-ancient-monument]; The lodge was built in medieval times [SUPPORTED: https://cannockchase.org.uk/care-for-the-chase/heritage-and-history/castle-ring-hill-fort/]; The building was a hunting lodge [SUPPORTED: https://cannockchase.org.uk/care-for-the-chase/heritage-and-history/castle-ring-hill-fort/]; The lodge''s remains are still visible [SUPPORTED: https://www.cannockchasedc.gov.uk/residents/leisure/countryside-service/castle-ring-scheduled-ancient-monument]; The fort is on the highest point of the Chase [SUPPORTED: https://www.cannockchasedc.gov.uk/residents/leisure/countryside-service/castle-ring-scheduled-ancient-monument]; The fort was abandoned as Romans occupied the area [SUPPORTED: https://cannockchase.org.uk/care-for-the-chase/heritage-and-history/castle-ring-hill-fort/]"}]'::jsonb),
    ('f7a58094-985b-4f4c-ad0e-c7d8b4c5c2f4'::uuid, 'card_description', 'Towers for the dead, square or rectangular, stand on the slopes of Pitaq Mach''ay. Declared a National Cultural Heritage in 2001, the complex also holds circular buildings.', 'On the slopes of Pitaq Mach''ay in the Huánuco Region, Tikra holds circular buildings and square or rectangular burial towers, a site declared National Cultural Heritage in 2001.', 'teaser-card-s048-rollback:f7a58094-985b-4f4c-ad0e-c7d8b4c5c2f4:card_description', 'rollback of teaser-card-s048: card_description "On the slopes of Pitaq Mach''ay in the Huánuco Region, Tikra holds circular buildings and square or rectangular burial towers, a site declared National Cultural Heritage in 2001." restored on Tikra', '80b9c2afca35dc4d27c1d0648c2eea57213ca3bb0e902344f519defb4e02ae34|72153c6bed1a7deb6f1424eb92f91204367efc3e65716526db7abc4e14006137|72153c6bed1a7deb6f1424eb92f91204367efc3e65716526db7abc4e14006137', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite2-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Towers for the dead, square or rectangular, stand on the slopes of Pitaq Mach''ay. Declared a National Cultural Heritage in 2001, the complex also holds circular buildings."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check2-002 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site has burial towers (towers for the dead) [S3]; the burial towers are square or rectangular [S3]; the towers stand on the slopes of Pitaq Mach''ay [S5]; the site was declared a National Cultural Heritage [S2]; the declaration was made in 2001 [S2]; the complex also holds circular buildings [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Towers for the dead stand at the site. [SUPPORTED: https://www.turismoperuano.com/sitio-arqueologico-de-ticra-huanuco]; The towers stand on the slopes of Pitaq Mach''ay. [SUPPORTED: https://www.turismoperuano.com/sitio-arqueologico-de-ticra-huanuco]; The towers for the dead are square or rectangular. [SUPPORTED: https://www.turismoperuano.com/sitio-arqueologico-de-ticra-huanuco]; The site was declared a National Cultural Heritage. [SUPPORTED: https://www.turismoperuano.com/sitio-arqueologico-de-ticra-huanuco]; The declaration was made in 2001. [SUPPORTED: https://www.turismoperuano.com/sitio-arqueologico-de-ticra-huanuco]; The complex also holds circular buildings. [SUPPORTED: https://www.turismoperuano.com/sitio-arqueologico-de-ticra-huanuco]"}]'::jsonb),
    ('f8beb699-0b16-4b18-b322-bdf7ca612ac9'::uuid, 'card_description', 'Orpheus charms all forms of life with his lyre in this villa''s mosaic. The mosaic has been uncovered seven times since 1880, and there are no plans to reveal it again.', 'Nothing of Woodchester Roman Villa is visible above ground, yet its Orpheus mosaic, the second largest of its kind in Europe, shows Orpheus charming all forms of life with his lyre.', 'teaser-card-s048-rollback:f8beb699-0b16-4b18-b322-bdf7ca612ac9:card_description', 'rollback of teaser-card-s048: card_description ''Nothing of Woodchester Roman Villa is visible above ground, yet its Orpheus mosaic, the second largest of its kind in Europe, shows Orpheus charming all forms of life with his lyre.'' restored on Woodchester Roman Villa', '477b1d189988ab027497e70d0816d7dcd13c2266f64fc01e9dff6a1659f6837b|9e6d723a2629eac69605daa8ba2e9356a85dd04269096d75c83881f6847f0ae5|9e6d723a2629eac69605daa8ba2e9356a85dd04269096d75c83881f6847f0ae5', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-020", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Orpheus charms all forms of life with his lyre in this villa''s mosaic. The mosaic has been uncovered seven times since 1880, and there are no plans to reveal it again."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the villa has a mosaic [S4]; the mosaic shows Orpheus charming all forms of life [S7]; Orpheus does so with his lyre [S7]; the mosaic has been uncovered seven times since 1880 [S6]; there are no plans to reveal it again [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Orpheus charms all forms of life with his lyre in this villa''s mosaic. [SUPPORTED: https://theyorkhistorian.com/2024/10/14/the-great-pavement/]; The mosaic belongs to a villa. [SUPPORTED: https://www.stroudlocalhistorysociety.org.uk/people-places/places/woodchester/roman/]; The mosaic has been uncovered seven times since 1880. [SUPPORTED: https://www.stroudlocalhistorysociety.org.uk/people-places/places/woodchester/roman/]; The run of uncoverings counted begins in 1880. [SUPPORTED: http://www.sinaiandsons.com/catalogue/19th%20Century/Orpheus%20Pavement/Orpheus%20Pavement.php]; The mosaic is covered today (it would have to be revealed again). [SUPPORTED: https://www.bradtguides.com/woodchester-mosaic/]; There are no plans to reveal it again. [SUPPORTED: https://www.bradtguides.com/woodchester-mosaic/]"}]'::jsonb),
    ('fae3bb4b-85fb-427a-a896-f32f4a2aa69c'::uuid, 'card_description', 'A rapier, a spearhead and a winged axe are among the bronze finds here. Neolithic pottery and flint artifacts have been found too, at a site of three round barrows and possibly a long one.', 'Three round barrows, and possibly a long chambered one, make up Battlegore Burial Chamber in Somerset, where bronze finds include a rapier, a spearhead, a winged axe and a broken dagger.', 'teaser-card-s048-rollback:fae3bb4b-85fb-427a-a896-f32f4a2aa69c:card_description', 'rollback of teaser-card-s048: card_description ''Three round barrows, and possibly a long chambered one, make up Battlegore Burial Chamber in Somerset, where bronze finds include a rapier, a spearhead, a winged axe and a broken dagger.'' restored on Battlegore Burial Chamber', '6f264b4f263daa4de7ed702122d22402022f5abf634577b7ff500f2231294ffa|ba71b0f6bbd77491adff4aa9f9e002e67df6876a0b08cff226d3f9411cde861e|ba71b0f6bbd77491adff4aa9f9e002e67df6876a0b08cff226d3f9411cde861e', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A rapier, a spearhead and a winged axe are among the bronze finds here. Neolithic pottery and flint artifacts have been found too, at a site of three round barrows and possibly a long one."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-005 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a rapier was found at the site [S6]; a spearhead was found at the site [S6]; a winged axe was found at the site [S6]; these are among (not all of) the bronze finds [S6]; Neolithic pottery has been found at the site [S5]; flint artifacts have been found at the site [S5]; the site consists of three round barrows [S2]; the site possibly includes a long barrow [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A rapier is among the bronze finds here. [SUPPORTED: https://sanhs.org/wp-content/uploads/SANH-165-Jones-Battlegore.pdf]; A spearhead is among the bronze finds here. [SUPPORTED: https://sanhs.org/wp-content/uploads/SANH-165-Jones-Battlegore.pdf]; A winged axe is among the bronze finds here. [SUPPORTED: https://sanhs.org/wp-content/uploads/SANH-165-Jones-Battlegore.pdf]; Bronze finds have been made here. [SUPPORTED: https://sanhs.org/wp-content/uploads/SANH-165-Jones-Battlegore.pdf]; Neolithic pottery has been found here. [SUPPORTED: https://sanhs.org/wp-content/uploads/SANH-165-Jones-Battlegore.pdf]; Flint artifacts have been found here too. [SUPPORTED: https://sanhs.org/wp-content/uploads/SANH-165-Jones-Battlegore.pdf]; The site has three round barrows. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=5277]; The site possibly has a long barrow. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=5277]"}]'::jsonb),
    ('ff7fc6c8-04f1-4988-954c-99c9b9f113e4'::uuid, 'card_description', 'Of the 22 towers on this Roman fort''s walls, 18 still survive. The oldest reference to the fortress comes from Pliny the Elder, and the town was also known for its theatre and hippodrome.', 'At the mouth of the Chorokhi river on the Black Sea, the Roman walls of Gonio Fortress still keep 18 of their 22 towers. Its oldest mention comes from Pliny the Elder, in the 1st century AD.', 'teaser-card-s048-rollback:ff7fc6c8-04f1-4988-954c-99c9b9f113e4:card_description', 'rollback of teaser-card-s048: card_description ''At the mouth of the Chorokhi river on the Black Sea, the Roman walls of Gonio Fortress still keep 18 of their 22 towers. Its oldest mention comes from Pliny the Elder, in the 1st century AD.'' restored on Gonio Fortress', '4e9c9c5d8992dfec534649a3a1208c2a53bc3ee5692a5606c0ea12b7c3abc23c|2b03a1d9fc49d7eb5cf05c19d0e3c052279f672be847d2cfcd7bc27c3c7d45a3|2b03a1d9fc49d7eb5cf05c19d0e3c052279f672be847d2cfcd7bc27c3c7d45a3', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-020", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Of the 22 towers on this Roman fort''s walls, 18 still survive. The oldest reference to the fortress comes from Pliny the Elder, and the town was also known for its theatre and hippodrome."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "it is a Roman fort [S1]; its walls had 22 towers [S8]; 18 of the towers still survive [S8]; the oldest reference to the fortress comes from Pliny the Elder [S2]; the town was known for its theatre [S4]; the town was known for its hippodrome [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This is a Roman fort with towers on its walls. [SUPPORTED: http://www.olkas.net/lemmata/18_Gonio-Apsaros]; There were 22 towers on the fort''s walls. [SUPPORTED: http://www.olkas.net/lemmata/18_Gonio-Apsaros]; 18 of the towers still survive. [SUPPORTED: https://antikmuseet.au.dk/fileadmin/www.antikmuseet.au.dk/Pontosfiler/BSS_8/BSS8_16_kakhidze.pdf]; The oldest reference to the fortress comes from Pliny the Elder. [SUPPORTED: http://www.olkas.net/lemmata/18_Gonio-Apsaros]; The town was also known for its theatre. [SUPPORTED: http://www.olkas.net/lemmata/18_Gonio-Apsaros]; The town was also known for its hippodrome. [SUPPORTED: http://www.olkas.net/lemmata/18_Gonio-Apsaros]"}]'::jsonb),
    ('ffb9aa8c-0ecc-4510-b18d-8555e319c427'::uuid, 'card_description', 'A propped stone, small cairns and a stone box grave lie on this hill. Two Bronze Age settlements and their field enclosures lie on the south and western slopes of the hill.', 'Leskernick Hill stands 329m high on Bodmin Moor. On its south and western slopes lie 2 Bronze Age settlements, with field enclosures, small cairns, a cist and a propped stone.', 'teaser-card-s048-rollback:ffb9aa8c-0ecc-4510-b18d-8555e319c427:card_description', 'rollback of teaser-card-s048: card_description ''Leskernick Hill stands 329m high on Bodmin Moor. On its south and western slopes lie 2 Bronze Age settlements, with field enclosures, small cairns, a cist and a propped stone.'' restored on Leskernick Hill', 'a22f568b31200351248a75823fd32dce6a8786b90327453b558f213f6c940dd8|f6121b3f1cac468b18e2e44ed6a29fa3f05d6b827f993f34e5f6e52755f39149|f6121b3f1cac468b18e2e44ed6a29fa3f05d6b827f993f34e5f6e52755f39149', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A propped stone, small cairns and a stone box grave lie on this hill. Two Bronze Age settlements and their field enclosures lie on the south and western slopes of the hill."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-010 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a hill [S1, S2]; a propped stone lies on the hill [S3]; small cairns lie on the hill [S3]; a stone box grave (a cist) lies on the hill [S3]; there are two settlements [S3]; the settlements are Bronze Age [S3]; the settlements have field enclosures [S3]; the settlements and enclosures lie on the south and western slopes [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-011 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Two settlements lie on this hill [SUPPORTED: https://intarch.ac.uk/journal/issue44/3/4-1.html]; The two settlements are Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Cornish_Bronze_Age]; The two settlements lie on the south and western slopes of the hill [SUPPORTED: https://www.cornish-times.co.uk/news/remote-stone-circle-added-to-at-risk-list-134625]; The settlements have field enclosures of their own [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=46737]; The field enclosures lie on the south and western slopes of the hill [SUPPORTED: https://www.cornish-times.co.uk/news/remote-stone-circle-added-to-at-risk-list-134625]; A propped stone lies on this hill [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=46474]; Small cairns lie on this hill [SUPPORTED: https://www.cornish-times.co.uk/news/remote-stone-circle-added-to-at-risk-list-134625]; A stone box grave lies on this hill [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=46737]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 38;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s048-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s048-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s048-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 38 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s048-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s048-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
